const DEEP: Record<string, Deepening> = {
  'de-frame/de-brief': {
    intro: B('In design, the request you receive is rarely the problem to solve. Clients describe a solution ("more modern", "like this competitor") because that is what they can see. This dojo teaches you to use the AI as a sorting tool: it separates what the request says from what it leaves out, under four headings, and refuses to fill the gaps. At the end, you will know how to turn any request into a brief you can design against, plus a short list of questions for the client.',
      "En design, la demande reçue est rarement le problème à résoudre. Les clients décrivent une solution (« plus moderne », « comme ce concurrent ») parce que c'est ce qu'ils voient. Ce dojo vous apprend à utiliser l'IA comme outil de tri : elle sépare ce que dit la demande de ce qu'elle omet, sous quatre rubriques, et refuse de combler les trous. À la fin, vous saurez transformer n'importe quelle demande en brief sur lequel concevoir, accompagné d'une courte liste de questions pour le client."),
    concepts: [
      { term: B('Brief', 'Brief'),
        def: B('A short document stating the problem, the audience, the constraints and the success criteria of a project. You design against it, and you defend your choices with it.',
          "Un document court qui énonce le problème, le public, les contraintes et les critères de réussite d'un projet. Vous concevez à partir de lui, et vous défendez vos choix grâce à lui.") },
      { term: B('Disguised solution', 'Solution déguisée'),
        def: B('A request phrased as an outcome the client already chose ("a carousel", "more premium"). It hides the problem that made them ask.',
          "Une demande formulée comme un résultat déjà choisi par le client (« un carrousel », « plus premium »). Elle cache le problème qui l'a poussé à demander.") },
      { term: B('Success criterion', 'Critère de réussite'),
        def: B('An observable sign that the design worked, checkable after launch without asking anyone\'s taste: a booking rate, a number of support calls, a task time.',
          "Un signe observable que le design a fonctionné, vérifiable après la mise en ligne sans demander l'avis de quiconque : un taux de réservation, un nombre d'appels au support, une durée de tâche.") },
      { term: B('Open question', 'Question ouverte'),
        def: B('A point the request does not settle and on which a design decision depends. Only these go back to the client.',
          "Un point que la demande ne tranche pas et dont dépend une décision de design. Seules ces questions repartent vers le client.") },
    ],
    walkthrough: {
      title: B('Léa turns "more modern and more welcoming" into a brief for a physiotherapy clinic',
        "Léa transforme « plus moderne et plus chaleureux » en brief pour un cabinet de kinésithérapie"),
      steps: [
        B('Léa pastes the client\'s email word for word, without rephrasing it. Why: her own summary would already contain an interpretation, and the model would build on it as if it were a fact.',
          "Léa colle le mail du client mot pour mot, sans le reformuler. Pourquoi : son propre résumé contiendrait déjà une interprétation, et le modèle la traiterait comme un fait."),
        B('She adds the three facts she knows for sure: three physiotherapists, one city, bookings by phone. Why: known facts give the model material to sort, instead of room to invent.',
          "Elle ajoute les trois faits qu'elle connaît avec certitude : trois kinés, une ville, des réservations par téléphone. Pourquoi : des faits connus donnent au modèle de quoi trier, au lieu d'un espace à remplir."),
        B('She asks for the four headings with the rule "write MISSING rather than guess". Why: the model naturally completes what is incomplete; the rule turns gaps into visible fields.',
          "Elle demande les quatre rubriques avec la règle « écris MANQUANT plutôt que de deviner ». Pourquoi : le modèle complète naturellement ce qui est incomplet ; la règle transforme les trous en champs visibles."),
        B('The result shows the problem and the success criteria as missing. She asks for the questions ranked by how much they change the design, and keeps five. Why: a busy client answers five questions, not fifteen.',
          "Le résultat signale le problème et les critères de réussite comme manquants. Elle demande les questions classées selon leur effet sur le design, et en garde cinq. Pourquoi : un client occupé répond à cinq questions, pas à quinze."),
        B('The client replies that the phone line is saturated every morning. Léa rewrites the problem: patients cannot book when the line is busy. Why: the problem now points to a flow, online booking, not to a style.',
          "Le client répond que la ligne est saturée chaque matin. Léa réécrit le problème : les patients ne peuvent pas réserver quand la ligne est occupée. Pourquoi : le problème désigne désormais un parcours, la réservation en ligne, et non un style."),
        B('She checks the brief: each success criterion is observable, no field contains a guess. Only then does she open her design tool.',
          "Elle vérifie le brief : chaque critère de réussite est observable, aucun champ ne contient de supposition. Alors seulement, elle ouvre son outil de design."),
      ],
    },
    mistakes: [
      { wrong: B('Asking the AI to "write the brief" from the request alone.',
          "Demander à l'IA de « rédiger le brief » à partir de la seule demande."),
        fix: B('Ask it to sort the request into four headings, mark every missing part, and never guess.',
          "Demandez-lui de ranger la demande en quatre rubriques, de signaler chaque partie manquante, et de ne jamais deviner.") },
      { wrong: B('Accepting a problem stated as a style: "the site is not modern enough".',
          "Accepter un problème formulé comme un style : « le site n'est pas assez moderne »."),
        fix: B('Ask "what goes wrong today, and how can we see it?" until the answer names a behavior or a number.',
          "Demandez « qu'est-ce qui ne va pas aujourd'hui, et comment le voit-on ? » jusqu'à obtenir un comportement ou un chiffre.") },
      { wrong: B('Sending the client all fifteen questions the AI produced.',
          "Envoyer au client les quinze questions produites par l'IA."),
        fix: B('Keep five at most, ranked by how much the answer would change the design, and drop those you can answer yourself.',
          "Gardez-en cinq au plus, classées selon ce que la réponse changerait au design, et retirez celles auxquelles vous pouvez répondre vous-même.") },
    ],
    recap: [
      B('A request is often a disguised solution: look for the problem behind it.', "Une demande est souvent une solution déguisée : cherchez le problème derrière."),
      B('Four headings: problem, audience, constraints, success criteria.', "Quatre rubriques : problème, public, contraintes, critères de réussite."),
      B('The AI sorts and flags the gaps; it never fills them with guesses.', "L'IA trie et signale les trous ; elle ne les comble jamais par des suppositions."),
      B('Only the open questions go back to the client, five at most.', "Seules les questions ouvertes repartent vers le client, cinq au plus."),
    ],
    further: B('Save your four-heading prompt as a reusable template in your AI tool, in a project or a saved instruction. At each new request, paste the email into it: you get the same structure every time, and you can compare briefs across clients.',
      "Enregistrez votre prompt à quatre rubriques comme modèle réutilisable dans votre outil IA, dans un projet ou une instruction enregistrée. À chaque nouvelle demande, collez-y le mail : vous obtenez la même structure à chaque fois, et vous pouvez comparer les briefs d'un client à l'autre."),
    more: [
      { q: B('You have ten minutes before a call about a vague request. What do you prepare with the AI?',
          "Vous avez dix minutes avant un appel sur une demande floue. Que préparez-vous avec l'IA ?"),
        options: [
          B('A first mockup to show during the call', "Une première maquette à montrer pendant l'appel"),
          B('A moodboard of three competitor sites', 'Un moodboard de trois sites concurrents'),
          B('The open questions, ranked by their effect on the design', 'Les questions ouvertes, classées selon leur effet sur le design'),
        ],
        answer: 2,
        why: B('A call is the cheapest moment to settle the problem. A mockup or a moodboard shown too early anchors the client on a style before anyone knows what must be solved.',
          "Un appel est le moment le moins coûteux pour clarifier le problème. Une maquette ou un moodboard montré trop tôt ancre le client sur un style avant que quiconque sache ce qu'il faut résoudre.") },
      { q: B('Which sentence states a problem rather than a disguised solution?',
          "Quelle phrase énonce un problème plutôt qu'une solution déguisée ?"),
        options: [
          B('"We need a carousel on the homepage"', '« Il nous faut un carrousel en page d\'accueil »'),
          B('"Half the visitors leave before seeing our prices"', '« La moitié des visiteurs partent avant de voir nos prix »'),
          B('"The site should look more premium"', '« Le site devrait faire plus premium »'),
          B('"We want the same layout as our competitor"', '« Nous voulons la même mise en page que notre concurrent »'),
        ],
        answer: 1,
        why: B('Only this sentence describes what goes wrong, with a sign you can measure. The three others already name an answer: a component, a style, a copy of someone else.',
          "Seule cette phrase décrit ce qui ne va pas, avec un signe mesurable. Les trois autres nomment déjà une réponse : un composant, un style, la copie d'un autre.") },
    ],
  },

  'de-frame/de-research': {
    intro: B('User research produces pages of notes, and the product team wants a few clear findings. The danger is compression: a model asked for "insights" merges voices, drops the counts and smooths the quotes. This dojo teaches a synthesis you can trace: participants labeled and anonymized, each finding with its count out of the total, exact quotes, and what contradicts it. At the end, you will produce a synthesis your team can check in a few minutes, and defend in a meeting.',
      "La recherche utilisateur produit des pages de notes, et l'équipe produit veut quelques constats clairs. Le danger est la compression : un modèle à qui l'on demande des « insights » fusionne les voix, perd les effectifs et lisse les citations. Ce dojo enseigne une synthèse traçable : participants étiquetés et anonymisés, chaque constat avec son effectif sur le total, des citations exactes et ce qui le contredit. À la fin, vous produirez une synthèse que votre équipe peut vérifier en quelques minutes et défendre en réunion."),
    concepts: [
      { term: B('Finding', 'Constat'),
        def: B('A statement about what participants said or did, supported by a count and by quotes. It describes; it does not yet propose a solution.',
          "Un énoncé sur ce que les participants ont dit ou fait, appuyé par un effectif et des citations. Il décrit ; il ne propose pas encore de solution.") },
      { term: B('Count', 'Effectif'),
        def: B('How many participants support a finding, out of the total: "7 of 12". It shows whether you hold a pattern or a lone signal.',
          "Le nombre de participants qui appuient un constat, sur le total : « 7 sur 12 ». Il montre si vous tenez une tendance ou un signal isolé.") },
      { term: B('Said versus done', 'Dit et fait'),
        def: B('The gap between what people report doing and what they were seen doing during the session. It is often where the design opportunity lies.',
          "L'écart entre ce que les gens déclarent faire et ce qu'on les a vus faire pendant la séance. C'est souvent là que se trouve l'occasion de design.") },
      { term: B('Pseudonymization', 'Pseudonymisation'),
        def: B('Replacing names and identifying details with labels (P1, P2) before sharing notes, and keeping the correspondence table offline, away from the AI tool.',
          "Le remplacement des noms et des détails identifiants par des étiquettes (P1, P2) avant de partager les notes, la table de correspondance restant hors ligne, loin de l'outil IA.") },
    ],
    walkthrough: {
      title: B('Karim synthesizes 12 interviews about a savings feature for Friday',
        "Karim synthétise 12 entretiens sur une fonction épargne pour vendredi"),
      steps: [
        B('Karim replaces every name with P1 to P12 and removes employers and cities, keeping the key in a local file. Why: the synthesis never needs identities, and participants did not agree to share them with a third-party tool.',
          "Karim remplace chaque nom par P1 à P12 et retire employeurs et villes, en gardant la correspondance dans un fichier local. Pourquoi : la synthèse n'a jamais besoin des identités, et les participants n'ont pas accepté leur envoi à un outil tiers."),
        B('He pastes one block per participant and states the research question at the top. Why: blocks let the model count and attribute; the question tells it what matters among the digressions.',
          "Il colle un bloc par participant et indique la question de recherche en tête. Pourquoi : les blocs permettent au modèle de compter et d'attribuer ; la question lui dit ce qui compte parmi les digressions."),
        B('He asks for findings with a count, exact quotes and contradictions, and separates said from done. Why: each element makes the synthesis checkable, and the said and done split exposes gaps between intentions and habits.',
          "Il demande des constats avec effectif, citations exactes et contradictions, et sépare le dit du fait. Pourquoi : chaque élément rend la synthèse vérifiable, et la séparation révèle les écarts entre intentions et habitudes."),
        B('One finding reads "7 of 12 say they save monthly; 2 of 12 have automatic savings set up". Why it matters: this gap is the design opportunity, invisible in a list of generic insights.',
          "Un constat indique « 7 sur 12 disent épargner chaque mois ; 2 sur 12 ont une épargne automatique ». Pourquoi c'est important : cet écart est l'occasion de design, invisible dans une liste d'insights génériques."),
        B('Karim searches his notes for five quotes. One is slightly reworded; he replaces it with the exact text. Why: a quote that changed wording may have changed meaning, and the team will quote it again.',
          "Karim cherche cinq citations dans ses notes. L'une est légèrement reformulée ; il la remplace par le texte exact. Pourquoi : une citation dont la formulation a changé a pu changer de sens, et l'équipe la citera à son tour."),
      ],
    },
    mistakes: [
      { wrong: B('Pasting notes with participants\' names, emails and employers.',
          "Coller des notes avec les noms, adresses et employeurs des participants."),
        fix: B('Replace identities with P1, P2 before pasting, and keep the correspondence table in a local file.',
          "Remplacez les identités par P1, P2 avant de coller, et gardez la table de correspondance dans un fichier local.") },
      { wrong: B('Presenting a finding with no count: "users want more control".',
          "Présenter un constat sans effectif : « les utilisateurs veulent plus de contrôle »."),
        fix: B('Require a count out of the total for every finding, and flag those resting on one person as lone signals.',
          "Exigez un effectif sur le total pour chaque constat, et signalez ceux qui reposent sur une personne comme signaux isolés.") },
      { wrong: B('Copying the AI\'s quotes into a presentation without checking them.',
          "Recopier les citations de l'IA dans une présentation sans les vérifier."),
        fix: B('Find each quote you will show in the raw notes, word for word, and fix any rewording before sharing.',
          "Retrouvez chaque citation que vous montrerez dans les notes brutes, mot pour mot, et corrigez toute reformulation avant de diffuser.") },
    ],
    recap: [
      B('Label and anonymize participants before pasting anything.', "Étiquetez et anonymisez les participants avant de coller quoi que ce soit."),
      B('Every finding carries a count out of the total and exact quotes.', "Chaque constat porte un effectif sur le total et des citations exactes."),
      B('Ask for contradictions: they keep the story honest.', "Demandez les contradictions : elles gardent le récit honnête."),
      B('Separate what people say from what they do.', "Séparez ce que les gens disent de ce qu'ils font."),
      B('Check quotes in the raw notes before they leave your desk.', "Vérifiez les citations dans les notes brutes avant toute diffusion."),
    ],
    further: B('After your next round of interviews, keep the labeled notes and the synthesis together. When the following round comes, give the AI both syntheses and ask which findings grew, which weakened and which appeared. You get a research history instead of isolated reports.',
      "Après votre prochaine série d'entretiens, conservez ensemble les notes étiquetées et la synthèse. Lors de la série suivante, donnez les deux synthèses à l'IA et demandez quels constats se renforcent, lesquels faiblissent et lesquels apparaissent. Vous obtenez un historique de recherche au lieu de rapports isolés."),
    more: [
      { q: B('A striking finding is supported by 1 participant out of 12. How do you present it?',
          "Un constat frappant est appuyé par 1 participant sur 12. Comment le présentez-vous ?"),
        options: [
          B('As a lone signal worth exploring in the next round', 'Comme un signal isolé à explorer lors de la prochaine série'),
          B('As a key finding, since it is so striking', "Comme un constat clé, puisqu'il est si frappant"),
          B('You leave it out, one person does not count', "Vous l'omettez, une personne ne compte pas"),
        ],
        answer: 0,
        why: B('One voice is not a pattern, but it can be a real problem others did not mention. Naming it a lone signal keeps it visible without letting it drive the roadmap.',
          "Une voix n'est pas une tendance, mais elle peut signaler un vrai problème que d'autres n'ont pas mentionné. La nommer signal isolé la garde visible sans lui laisser piloter la feuille de route.") },
      { q: B('9 of 12 participants say they compare prices before buying, but the session recordings show 3 did. What do you report?',
          "9 participants sur 12 disent comparer les prix avant d'acheter, mais les enregistrements montrent que 3 l'ont fait. Que rapportez-vous ?"),
        options: [
          B('That 9 of 12 compare prices', 'Que 9 sur 12 comparent les prix'),
          B('That 3 of 12 compare prices, nothing else', 'Que 3 sur 12 comparent les prix, sans plus'),
          B('An average of the two figures', 'Une moyenne des deux chiffres'),
          B('Both figures, and the gap as a finding', "Les deux chiffres, et l'écart comme constat"),
        ],
        answer: 3,
        why: B('Each figure is true about something different: intention and behavior. The gap between them is itself the most useful finding for design.',
          "Chaque chiffre est vrai à propos d'une chose différente : l'intention et le comportement. L'écart entre eux est lui-même le constat le plus utile au design.") },
    ],
  },

  'de-frame/de-moodboard': {
    intro: B('A moodboard is supposed to align a client and a team on a direction before production. Made of images alone, it often does the opposite: everyone reads something different into it, and references drift into the final work without anyone checking who owns them. This dojo teaches you to write directions in words, test them against the brief with the AI, and keep a source and a borrowed element for every reference. You will leave with moodboards that argue for a choice and protect you on rights.',
      "Un moodboard est censé aligner un client et une équipe sur une direction avant la production. Fait uniquement d'images, il produit souvent l'inverse : chacun y lit autre chose, et des références glissent dans le travail final sans que personne ne vérifie à qui elles appartiennent. Ce dojo vous apprend à écrire les directions en mots, à les confronter au brief avec l'IA, et à garder une source et un élément emprunté pour chaque référence. Vous repartirez avec des moodboards qui défendent un choix et vous protègent sur les droits."),
    concepts: [
      { term: B('Direction', 'Direction'),
        def: B('A coherent visual intention for a project, stated in words: what it is and where it stops. Several directions are compared before one is chosen.',
          "Une intention visuelle cohérente pour un projet, énoncée en mots : ce qu'elle est et où elle s'arrête. On compare plusieurs directions avant d'en retenir une.") },
      { term: B('Bounded adjective', 'Adjectif borné'),
        def: B('An adjective paired with the limit it must not cross: "warm, not rustic". The limit removes the readings you would reject anyway.',
          "Un adjectif associé à la limite qu'il ne doit pas franchir : « chaleureux, pas rustique ». La limite écarte les lectures que vous rejetteriez de toute façon.") },
      { term: B('Borrowed element', 'Élément emprunté'),
        def: B('The precise property you take from a reference (a grid, a crop, a palette), as opposed to the image itself, which remains someone else\'s work.',
          "La propriété précise que vous retenez d'une référence (une grille, un cadrage, une palette), par opposition à l'image elle-même, qui reste l'oeuvre de quelqu'un d'autre.") },
    ],
    walkthrough: {
      title: B('Inès prepares three directions for an organic bakery before a client meeting',
        "Inès prépare trois directions pour une boulangerie bio avant un rendez-vous client"),
      steps: [
        B('Inès writes the brief in three lines: office workers buying lunch fast, the belief that organic means expensive and slow, a city-center shop. Why: the directions will be judged against this, not against her taste.',
          "Inès écrit le brief en trois lignes : des salariés qui achètent leur déjeuner vite, la croyance que bio veut dire cher et lent, une boutique en centre-ville. Pourquoi : les directions seront jugées au regard de ce texte, et non de son goût."),
        B('She writes each direction as two bounded adjectives: "warm, not rustic; generous, not cluttered". Why: the limits make each direction distinct and give the model something precise to test.',
          "Elle écrit chaque direction avec deux adjectifs bornés : « chaleureux, pas rustique ; généreux, pas encombré ». Pourquoi : les limites rendent chaque direction distincte et donnent au modèle un objet précis à tester."),
        B('She asks the AI, for each direction, which part of the brief it serves, which it ignores, and one risk with this audience. Why: this forces an argument rather than a ranking by preference.',
          "Elle demande à l'IA, pour chaque direction, quelle partie du brief elle sert, laquelle elle ignore, et un risque auprès de ce public. Pourquoi : cela impose un argument plutôt qu'un classement par préférence."),
        B('The AI notes that her favorite direction reinforces "organic means slow and traditional". Inès leads with another direction and keeps one property of her favorite, its palette. Why: the brief wins, but good ideas survive as details.',
          "L'IA relève que sa direction préférée renforce l'idée « bio égale lent et traditionnel ». Inès ouvre avec une autre direction et garde une propriété de sa favorite, sa palette. Pourquoi : le brief l'emporte, mais les bonnes idées survivent en détail."),
        B('For each reference on the board, she writes the source and the borrowed element, and marks all of them as "reference only". Why: when the final design is made, nobody will paste one of these images into it.',
          "Pour chaque référence de la planche, elle note la source et l'élément emprunté, et les marque toutes « référence seulement ». Pourquoi : lors de la conception finale, personne n'y collera l'une de ces images."),
      ],
    },
    mistakes: [
      { wrong: B('Presenting a board of images with no words and letting the client "feel it".',
          "Présenter une planche d'images sans mots en laissant le client « ressentir »."),
        fix: B('Add two bounded adjectives per direction under the images, so everyone reads the same intention.',
          "Ajoutez deux adjectifs bornés par direction sous les images, pour que chacun lise la même intention.") },
      { wrong: B('Asking the AI which direction is "the most beautiful".',
          "Demander à l'IA quelle direction est « la plus belle »."),
        fix: B('Ask which part of the brief each direction serves and ignores, and which risk it carries with this audience.',
          "Demandez quelle partie du brief chaque direction sert et ignore, et quel risque elle comporte auprès de ce public.") },
      { wrong: B('Keeping screenshots of other studios\' work with no source.',
          "Conserver des captures du travail d'autres studios sans source."),
        fix: B('Note the source and the borrowed element for each, and label them reference only, never for use in the delivery.',
          "Notez pour chacune la source et l'élément emprunté, et marquez-les référence seulement, jamais pour la livraison.") },
    ],
    recap: [
      B('Write each direction in words, with two bounded adjectives.', "Écrivez chaque direction en mots, avec deux adjectifs bornés."),
      B('Test directions against the brief, not against taste.', "Confrontez les directions au brief, et non au goût."),
      B('A reference lends a property, never its image.', "Une référence prête une propriété, jamais son image."),
      B('Every reference keeps its source, for rights and for honesty.', "Chaque référence garde sa source, pour les droits comme pour l'honnêteté."),
    ],
    further: B('Build a personal reference library in a simple table: image link, source, borrowed element, the projects where it helped. Before your next moodboard, ask the AI to suggest which of your past references fit the new brief\'s bounded adjectives.',
      "Constituez une bibliothèque personnelle de références dans un simple tableau : lien de l'image, source, élément emprunté, projets où elle a servi. Avant votre prochain moodboard, demandez à l'IA lesquelles de vos références passées correspondent aux adjectifs bornés du nouveau brief."),
    more: [
      { q: B('A client asks to use one of the moodboard images directly on their homepage. What do you answer?',
          "Un client demande d'utiliser directement l'une des images du moodboard sur sa page d'accueil. Que répondez-vous ?"),
        options: [
          B('Yes, since it was already in the approved moodboard', 'Oui, puisqu\'elle figurait dans le moodboard validé'),
          B('Not without a license from its owner; you propose an original', "Pas sans licence de son propriétaire ; vous proposez un original"),
          B('Yes, if you crop it enough to change its look', "Oui, si vous la recadrez assez pour en changer l'aspect"),
        ],
        answer: 1,
        why: B('Approval of a moodboard does not transfer any rights. The image belongs to its author; using it requires a license, and cropping does not change that.',
          "La validation d'un moodboard ne transfère aucun droit. L'image appartient à son auteur ; l'utiliser exige une licence, et un recadrage n'y change rien.") },
      { q: B('Which direction wording will give the client and the team the same picture?',
          "Quelle formulation de direction donnera la même image au client et à l'équipe ?"),
        options: [
          B('"Modern and elegant"', '« Moderne et élégant »'),
          B('"Like the Apple website"', '« Comme le site d\'Apple »'),
          B('"Calm, not sleepy; precise, not cold"', '« Calme, pas endormi ; précis, pas froid »'),
        ],
        answer: 2,
        why: B('Each limit removes a whole family of interpretations. "Modern" alone can mean anything, and pointing to a famous brand invites copying rather than a direction.',
          "Chaque limite écarte toute une famille d'interprétations. « Moderne » seul peut tout dire, et désigner une marque célèbre invite à copier plutôt qu'à définir une direction.") },
    ],
  },

  'de-make/de-directions': {
    intro: B('Image generation lets a designer explore more directions in an hour than in a day of sketching. Used carelessly, it produces piles of images that differ for random reasons, and borrows other people\'s styles. This dojo applies a designer\'s method to generation: a fixed base, one axis changed per version, styles described by their properties, and outputs treated as sketches to redraw. At the end, you will explore visual directions quickly while keeping the result original and yours.',
      "La génération d'images permet à un designer d'explorer plus de directions en une heure qu'en une journée d'esquisses. Mal employée, elle produit des piles d'images qui diffèrent pour des raisons aléatoires, et emprunte le style des autres. Ce dojo applique à la génération une méthode de designer : une base fixe, un seul axe modifié par version, des styles décrits par leurs propriétés, et des résultats traités comme des esquisses à redessiner. À la fin, vous explorerez rapidement des directions visuelles tout en gardant un résultat original et le vôtre."),
    concepts: [
      { term: B('Base description', 'Description de base'),
        def: B('The part of the prompt that stays word for word identical across versions: subject, format, audience, the message to convey, the space kept for text.',
          "La partie du prompt qui reste identique mot pour mot d'une version à l'autre : sujet, format, public, message à transmettre, espace réservé au texte.") },
      { term: B('Design axis', 'Axe de design'),
        def: B('One dimension you vary on purpose: palette, composition, type treatment, lighting. Changing one axis at a time shows what it does.',
          "Une dimension que vous faites varier volontairement : palette, composition, traitement typographique, lumière. Changer un axe à la fois montre ce qu'il produit.") },
      { term: B('Style properties', 'Propriétés de style'),
        def: B('The describable features of a style (line weight, texture, color treatment, level of detail). They replace an artist\'s name and give a direction of your own.',
          "Les caractéristiques descriptibles d'un style (épaisseur du trait, texture, traitement des couleurs, niveau de détail). Elles remplacent le nom d'un artiste et donnent une direction qui vous appartient.") },
      { term: B('Exploration sketch', "Esquisse d'exploration"),
        def: B('A generated image used to decide, not to deliver. The chosen idea is then redrawn or rebuilt by the designer.',
          "Une image générée qui sert à décider, non à livrer. L'idée retenue est ensuite redessinée ou reconstruite par le designer.") },
    ],
    walkthrough: {
      title: B('Hugo explores a jazz festival poster in three controlled versions',
        "Hugo explore une affiche de festival de jazz en trois versions contrôlées"),
      steps: [
        B('Hugo writes the base: vertical poster, open-air festival by a river, local families, the message "relaxed and open to everyone", space for the title at the top. Why: the base carries the brief into every version.',
          "Hugo écrit la base : affiche verticale, festival en plein air au bord d'une rivière, familles du coin, le message « détendu et ouvert à tous », espace pour le titre en haut. Pourquoi : la base porte le brief dans chaque version."),
        B('He replaces the client\'s "in the style of" request with three properties: flat shapes, thick outlines, paper grain. Why: the look becomes describable and his own, with no living artist imitated.',
          "Il remplace le « dans le style de » du client par trois propriétés : aplats, contours épais, grain de papier. Pourquoi : le rendu devient descriptible et le sien, sans imiter un artiste vivant."),
        B('He generates three versions, each changing a single axis: palette, title treatment, composition. Why: when one version works better, he knows exactly which choice caused it.',
          "Il génère trois versions, chacune modifiant un seul axe : palette, traitement du titre, composition. Pourquoi : quand une version fonctionne mieux, il sait exactement quel choix en est la cause."),
        B('He writes one sentence per version about what the axis changed. The composition with the musician seen from behind, facing the crowd, carries "open to everyone" best. Why: the note turns images into a decision he can explain to the client.',
          "Il écrit une phrase par version sur ce que l'axe a changé. La composition avec le musicien de dos, face à la foule, porte le mieux « ouvert à tous ». Pourquoi : la note transforme des images en décision qu'il peut expliquer au client."),
        B('He draws the final poster himself from that composition, and checks that no generated element, logo or recognizable face remains. Why: the delivery is original work, and the client receives no hidden rights problem.',
          "Il dessine lui-même l'affiche finale à partir de cette composition, et vérifie qu'il ne reste aucun élément généré, logo ou visage reconnaissable. Pourquoi : la livraison est une oeuvre originale, et le client ne reçoit aucun problème de droits caché."),
      ],
    },
    mistakes: [
      { wrong: B('Rewriting the whole prompt between two versions.',
          "Réécrire tout le prompt entre deux versions."),
        fix: B('Copy the base word for word and change only the line of the axis you are testing.',
          "Recopiez la base mot pour mot et ne changez que la ligne de l'axe testé.") },
      { wrong: B('Typing "in the style of" followed by a living illustrator\'s name.',
          "Taper « dans le style de » suivi du nom d'un illustrateur vivant."),
        fix: B('Describe three or four visual properties instead, and build your own direction from them.',
          "Décrivez plutôt trois ou quatre propriétés visuelles, et construisez votre propre direction à partir d'elles.") },
      { wrong: B('Delivering a generated image as the final asset without checking it.',
          "Livrer une image générée comme visuel final sans la vérifier."),
        fix: B('Redraw or rebuild the idea, or at least check for marks, faces and text, and confirm the tool\'s terms on commercial use.',
          "Redessinez ou reconstruisez l'idée, ou vérifiez au moins marques, visages et textes, et confirmez les conditions d'usage commercial de l'outil.") },
    ],
    recap: [
      B('A fixed base, one changed axis per version.', "Une base fixe, un seul axe modifié par version."),
      B('Describe styles by properties, never by a living artist\'s name.', "Décrivez un style par ses propriétés, jamais par le nom d'un artiste vivant."),
      B('Write what each axis changed: images become decisions.', "Notez ce que chaque axe a changé : les images deviennent des décisions."),
      B('Generated images are sketches; the delivery is your work.', "Les images générées sont des esquisses ; la livraison est votre travail."),
    ],
    further: B('Keep a small "axis log" per project: the base, each version, and your one-line note. After a few projects, ask the AI to summarize which axes most often changed the outcome for your kind of client. You will learn where to start exploring next time.',
      "Tenez un petit « journal des axes » par projet : la base, chaque version et votre note d'une ligne. Après quelques projets, demandez à l'IA de résumer quels axes ont le plus souvent changé le résultat pour votre type de client. Vous saurez par où commencer l'exploration la fois suivante."),
    more: [
      { q: B('You want to test whether a darker palette works better. What must stay identical?',
          "Vous voulez tester si une palette plus sombre fonctionne mieux. Qu'est-ce qui doit rester identique ?"),
        options: [
          B('Only the subject of the image', "Seulement le sujet de l'image"),
          B('The whole base, including composition and style', 'Toute la base, composition et style compris'),
          B('Nothing, since generation is random anyway', 'Rien, puisque la génération est aléatoire de toute façon'),
        ],
        answer: 1,
        why: B('Generation has some randomness, which is exactly why everything else must stay fixed. If composition also changes, you cannot tell what the darker palette did.',
          "La génération comporte une part d'aléatoire : c'est justement pourquoi tout le reste doit rester fixe. Si la composition change aussi, vous ne pouvez pas savoir ce qu'a produit la palette sombre.") },
      { q: B('What replaces "in the style of [living artist]" in a professional prompt?',
          "Qu'est-ce qui remplace « dans le style de [artiste vivant] » dans un prompt professionnel ?"),
        options: [
          B('The name of a dead artist instead', "Le nom d'un artiste décédé à la place"),
          B('The word "original" at the end of the prompt', 'Le mot « original » en fin de prompt'),
          B('The name of a famous design studio', "Le nom d'un studio de design célèbre"),
          B('A list of visual properties: line, texture, color', 'Une liste de propriétés visuelles : trait, texture, couleur'),
        ],
        answer: 3,
        why: B('Properties give the model something precise to render and give you a direction you own. Swapping one name for another, or adding "original", does not solve the problem.',
          "Les propriétés donnent au modèle un objet précis à rendre et vous donnent une direction qui vous appartient. Remplacer un nom par un autre, ou ajouter « original », ne règle rien.") },
    ],
  },

  'de-make/de-critique': {
    intro: B('Feedback is only useful if you can act on it, and a model asked "what do you think?" gives polite, generic remarks. This dojo turns the AI into a structured reviewer: you give it the screen\'s goal, the user\'s task and three criteria from the brief, and it returns problems tied to a criterion, located on the screen and ranked by severity. You will learn to separate problems from taste, to decide what to fix first, and to confirm the top problem with a real person before redesigning.',
      "Un retour n'est utile que si l'on peut agir dessus, et un modèle à qui l'on demande « qu'en penses-tu ? » livre des remarques polies et génériques. Ce dojo fait de l'IA un relecteur structuré : vous lui donnez l'objectif de l'écran, la tâche de l'utilisateur et trois critères du brief, et elle renvoie des problèmes reliés à un critère, situés à l'écran et classés par gravité. Vous apprendrez à séparer les problèmes du goût, à décider quoi corriger d'abord, et à confirmer le premier problème avec une vraie personne avant de reprendre le design."),
    concepts: [
      { term: B('Criterion', 'Critère'),
        def: B('A requirement from the brief, stated so it can be checked: "a new patient books in under a minute". Every problem must name the one it threatens.',
          "Une exigence du brief, formulée pour pouvoir être vérifiée : « un nouveau patient réserve en moins d'une minute ». Chaque problème doit nommer celle qu'il menace.") },
      { term: B('Severity', 'Gravité'),
        def: B('How much a problem blocks the main task: blocking (the task fails), serious (it is slowed or error-prone), minor (it is only less pleasant).',
          "Le degré auquel un problème entrave la tâche principale : bloquant (la tâche échoue), sérieux (elle est ralentie ou source d'erreurs), mineur (elle est seulement moins agréable).") },
      { term: B('Taste remark', 'Remarque de goût'),
        def: B('A comment that fits no criterion ("the font feels dated"). It is kept aside, because it may reveal a criterion the brief forgot, or simply be opinion.',
          "Un commentaire qui ne relève d'aucun critère (« la police fait daté »). On le met de côté, car il peut révéler un critère oublié par le brief, ou n'être qu'une opinion.") },
    ],
    walkthrough: {
      title: B('Sofia gets an actionable critique of a booking screen before a client review',
        "Sofia obtient une critique exploitable d'un écran de réservation avant une revue client"),
      steps: [
        B('Sofia writes the goal of the screen (book a first appointment without calling) and the user task (practitioner, reason, slot, confirm). Why: without a goal, the model can only judge appearance.',
          "Sofia écrit l'objectif de l'écran (réserver un premier rendez-vous sans téléphoner) et la tâche (praticien, motif, créneau, confirmation). Pourquoi : sans objectif, le modèle ne peut juger que l'apparence."),
        B('She copies three criteria from the brief, including "patients over 65 read and tap everything comfortably". Why: criteria are the standard each remark will be measured against.',
          "Elle recopie trois critères du brief, dont « les patients de plus de 65 ans lisent et touchent tout confortablement ». Pourquoi : les critères sont la référence à laquelle chaque remarque sera mesurée."),
        B('She asks for problems with criterion, location, severity and fix, no praise, and a separate taste list. Why: this format turns opinions into a ranked, checkable list.',
          "Elle demande les problèmes avec critère, emplacement, gravité et correction, sans compliments, et une liste de goût à part. Pourquoi : ce format transforme des avis en liste classée et vérifiable."),
        B('The top problem: the reason for the visit comes after the slot, so first-time patients pick slots that are too short. Why it ranks first: it breaks the main task, not the look.',
          "Premier problème : le motif arrive après le créneau, et les nouveaux patients choisissent des créneaux trop courts. Pourquoi il arrive en tête : il casse la tâche principale, pas l'apparence."),
        B('Before redesigning, Sofia asks a colleague who has never seen the screen to book a first visit. The colleague picks a 20-minute slot for a 45-minute first session. Why: the test confirms the problem with a person, not only with the model.',
          "Avant de reprendre le design, Sofia demande à une collègue qui n'a jamais vu l'écran de réserver une première visite. La collègue choisit un créneau de 20 minutes pour une séance de 45. Pourquoi : le test confirme le problème avec une personne, pas seulement avec le modèle."),
      ],
    },
    mistakes: [
      { wrong: B('Sharing only the screen and asking for "feedback".',
          "Partager seulement l'écran et demander « des retours »."),
        fix: B('Add the goal, the user task and three criteria from the brief, and require each problem to name a criterion.',
          "Ajoutez l'objectif, la tâche de l'utilisateur et trois critères du brief, et exigez que chaque problème nomme un critère.") },
      { wrong: B('Fixing every remark in the order the AI listed them.',
          "Corriger chaque remarque dans l'ordre où l'IA les a listées."),
        fix: B('Ask for a ranking by severity on the main task, and start with the one or two blocking problems.',
          "Demandez un classement par gravité sur la tâche principale, et commencez par les un ou deux problèmes bloquants.") },
      { wrong: B('Treating the AI\'s critique as a usability test.',
          "Considérer la critique de l'IA comme un test utilisateur."),
        fix: B('Use it to decide what to test, then watch at least one real person try the task before redesigning.',
          "Servez-vous-en pour choisir quoi tester, puis observez au moins une vraie personne tenter la tâche avant de reprendre le design.") },
    ],
    recap: [
      B('Give the goal, the task and three criteria before asking for critique.', "Donnez l'objectif, la tâche et trois critères avant de demander une critique."),
      B('Each problem names a criterion, a place and a severity.', "Chaque problème nomme un critère, un endroit et une gravité."),
      B('Taste goes in a separate list, read once for forgotten criteria.', "Le goût va dans une liste à part, relue une fois pour repérer un critère oublié."),
      B('Confirm the top problem with a real person before changing the design.', "Confirmez le premier problème avec une vraie personne avant de modifier le design."),
    ],
    further: B('Save your critique prompt with your team\'s standing criteria (accessibility, brand, performance) as a checklist. Run it on every screen before design review: the meeting can then discuss the few real trade-offs instead of spotting obvious issues.',
      "Enregistrez votre prompt de critique avec les critères permanents de votre équipe (accessibilité, marque, performance) comme liste de contrôle. Lancez-le sur chaque écran avant la revue de design : la réunion peut alors discuter des quelques vrais arbitrages au lieu de relever les défauts évidents."),
    more: [
      { q: B('The AI starts its critique with three paragraphs of praise. What do you change in your prompt?',
          "L'IA commence sa critique par trois paragraphes de compliments. Que changez-vous dans votre prompt ?"),
        options: [
          B('Ask for problems only, ranked by severity, and no praise', 'Demander seulement les problèmes, classés par gravité, sans compliments'),
          B('Ask it to be much harsher and more critical in tone', 'Lui demander un registre beaucoup plus dur et critique'),
          B('Nothing, the praise shows what works', 'Rien, les compliments montrent ce qui fonctionne'),
        ],
        answer: 0,
        why: B('Praise takes space and softens the ranking. Asking for harshness changes the tone but not the structure; asking for problems with criteria and severity changes what you get.',
          "Les compliments prennent de la place et adoucissent le classement. Demander de la dureté change le registre, pas la structure ; demander des problèmes avec critères et gravité change ce que vous obtenez.") },
      { q: B('A remark says "the icons feel old-fashioned". None of your criteria covers it. What do you do?',
          "Une remarque dit « les icônes font démodé ». Aucun de vos critères ne la couvre. Que faites-vous ?"),
        options: [
          B('Redesign all the icons before the review', 'Redessiner toutes les icônes avant la revue'),
          B('Put it in the taste list and check if a criterion is missing', 'La mettre dans la liste de goût et vérifier si un critère manque'),
          B('Delete it, the AI has no taste', "La supprimer, l'IA n'a pas de goût"),
        ],
        answer: 1,
        why: B('If the brief says the brand must look current, the remark reveals a missing criterion. If not, it is opinion. The taste list lets you decide once, calmly.',
          "Si le brief exige une marque actuelle, la remarque révèle un critère manquant. Sinon, c'est une opinion. La liste de goût permet de trancher une fois, posément.") },
    ],
  },

  'de-make/de-microcopy': {
    intro: B('Interface text is design: a clear error message can save a sale, a vague one sends people to support. The words are short, which makes them look easy, and a model asked for "friendly" text will produce tone rather than information. This dojo teaches you to brief the AI like a UX writer: the exact situation, the space in characters, the product\'s own words, and a rule that every message ends with an action. You will leave able to write and check error messages, empty states and labels quickly.',
      "Le texte d'interface fait partie du design : un message d'erreur clair peut sauver une vente, un message vague envoie les gens vers le support. Les mots sont courts, ce qui les fait paraître faciles, et un modèle à qui l'on demande du texte « sympa » produit du registre plutôt que de l'information. Ce dojo vous apprend à briefer l'IA comme un rédacteur UX : la situation exacte, la place en caractères, les mots du produit, et la règle selon laquelle chaque message se termine par une action. Vous saurez rédiger et vérifier rapidement messages d'erreur, états vides et libellés."),
    concepts: [
      { term: B('Microcopy', 'Microcopy'),
        def: B('The short texts of an interface: labels, error messages, empty states, confirmations, hints. They guide the user at the exact moment of action.',
          "Les textes courts d'une interface : libellés, messages d'erreur, états vides, confirmations, indications. Ils guident l'utilisateur au moment précis de l'action.") },
      { term: B('Error message anatomy', "Anatomie d'un message d'erreur"),
        def: B('Three parts in this order: what happened, what it means for the user (is the data or money safe), and what to do now.',
          "Trois parties dans cet ordre : ce qui s'est passé, ce que cela implique pour l'utilisateur (données ou argent préservés ?), et ce qu'il doit faire maintenant.") },
      { term: B('Product vocabulary', 'Vocabulaire du produit'),
        def: B('The words your interface already uses for its objects and actions. Reusing them everywhere keeps the user from wondering whether "trip" and "journey" are two different things.',
          "Les mots que votre interface emploie déjà pour ses objets et ses actions. Les reprendre partout évite à l'utilisateur de se demander si « trajet » et « voyage » désignent deux choses différentes.") },
    ],
    walkthrough: {
      title: B('Thomas rewrites the "seat taken during payment" error of a train app',
        "Thomas réécrit l'erreur « place prise pendant le paiement » d'une application de train"),
      steps: [
        B('Thomas describes the exact situation: the user was paying, someone else took the seat, the user was not charged, other seats remain. Why: the model can only name a cause and reassure if it knows them.',
          "Thomas décrit la situation exacte : l'utilisateur payait, quelqu'un a pris la place, l'utilisateur n'a pas été débité, d'autres places restent. Pourquoi : le modèle ne peut nommer la cause et rassurer que s'il les connaît."),
        B('He gives the space: title 40 characters, body 90, action 20. Why: the limit forces the model to choose what matters instead of adding apologies and explanations.',
          "Il indique la place : titre de 40 caractères, corps de 90, action de 20. Pourquoi : la limite oblige le modèle à choisir l'essentiel au lieu d'ajouter excuses et explications."),
        B('He lists the product words (seat, trip, choose) and the banned ones (transaction, booking). Why: consistent vocabulary is what makes an interface feel simple.',
          "Il liste les mots du produit (place, trajet, choisir) et les mots interdits (transaction, réservation). Pourquoi : un vocabulaire constant est ce qui rend une interface simple."),
        B('Among three versions, he keeps "This seat was just taken / You have not been charged. Other seats are free on this train. / Choose another seat". Why: cause, reassurance and action, in that order.',
          "Parmi trois versions, il garde « Cette place vient d'être prise / Vous n'avez pas été débité. D'autres places sont libres dans ce train. / Choisir une place ». Pourquoi : cause, réassurance et action, dans cet ordre."),
        B('He counts the characters with a tool and reads the message aloud as a stressed traveler would hear it. Why: model counts are unreliable, and blame or jargon is easier to hear than to see.',
          "Il compte les caractères avec un outil et lit le message à voix haute comme l'entendrait un voyageur stressé. Pourquoi : les comptes du modèle sont peu fiables, et reproche ou jargon s'entendent mieux qu'ils ne se voient."),
      ],
    },
    mistakes: [
      { wrong: B('Asking for a "friendly" or "fun" error message.',
          "Demander un message d'erreur « sympa » ou « drôle »."),
        fix: B('Describe what happened and what the user can do, then ask for cause, consequence and action within a character limit.',
          "Décrivez ce qui s'est passé et ce que l'utilisateur peut faire, puis demandez cause, conséquence et action dans une limite de caractères.") },
      { wrong: B('Ending a message with "Please try again later".',
          "Terminer un message par « Veuillez réessayer plus tard »."),
        fix: B('End with a concrete action the user can take now, or say when the problem will be solved if you know.',
          "Terminez par une action concrète que l'utilisateur peut faire maintenant, ou dites quand le problème sera résolu si vous le savez.") },
      { wrong: B('Trusting the character count the AI announces.',
          "Se fier au nombre de caractères annoncé par l'IA."),
        fix: B('Count with a tool or in your design file, where the text either fits the component or does not.',
          "Comptez avec un outil ou dans votre fichier de design, où le texte tient dans le composant ou non.") },
    ],
    recap: [
      B('Describe the situation precisely: what failed, what is safe, what remains possible.', "Décrivez la situation avec précision : ce qui a échoué, ce qui est préservé, ce qui reste possible."),
      B('Give the space in characters and the product\'s own words.', "Donnez la place en caractères et les mots du produit."),
      B('Every message ends with an action the user can take.', "Chaque message se termine par une action que l'utilisateur peut faire."),
      B('Count characters yourself and read the text aloud.', "Comptez les caractères vous-même et lisez le texte à voix haute."),
    ],
    further: B('Collect the ten most frequent error messages of your product in a table: situation, current text, space. Ask the AI to rewrite them all with the same rules and the same vocabulary, then review them with a developer who knows when each one appears.',
      "Rassemblez dans un tableau les dix messages d'erreur les plus fréquents de votre produit : situation, texte actuel, place disponible. Demandez à l'IA de tous les réécrire avec les mêmes règles et le même vocabulaire, puis relisez-les avec un développeur qui sait quand chacun apparaît."),
    more: [
      { q: B('An empty inbox screen says "No data". What would a better empty state do?',
          "Un écran de boîte de réception vide affiche « Aucune donnée ». Que ferait un meilleur état vide ?"),
        options: [
          B('Show a large illustration and nothing else', 'Afficher une grande illustration, et rien d\'autre'),
          B('Explain why it is empty and offer the next action', "Expliquer pourquoi c'est vide et proposer l'action suivante"),
          B('Hide the screen until data arrives', "Masquer l'écran jusqu'à l'arrivée de données"),
        ],
        answer: 1,
        why: B('An empty state is a moment of doubt: is it broken, or is there nothing yet? Saying why and offering an action ("Invite a colleague to start") turns it into a step forward.',
          "Un état vide est un moment de doute : est-ce cassé, ou n'y a-t-il encore rien ? Dire pourquoi et proposer une action (« Invitez un collègue pour commencer ») en fait un pas en avant.") },
      { q: B('Your app says "trip" everywhere, but the AI\'s message says "journey". What do you do?',
          "Votre application dit « trajet » partout, mais le message de l'IA dit « voyage ». Que faites-vous ?"),
        options: [
          B('Keep "journey", it sounds warmer', 'Garder « voyage », il sonne plus chaleureux'),
          B('Replace "trip" everywhere with "journey"', 'Remplacer « trajet » par « voyage » partout'),
          B('Use "trip", and add your vocabulary to the prompt', 'Employer « trajet », et ajouter votre vocabulaire au prompt'),
        ],
        answer: 2,
        why: B('A new word for the same thing makes users wonder if it is something else. Fix the message, then put the product vocabulary in the prompt so it does not happen again.',
          "Un nouveau mot pour la même chose fait croire à l'utilisateur qu'il s'agit d'autre chose. Corrigez le message, puis mettez le vocabulaire du produit dans le prompt pour que cela ne se reproduise pas.") },
    ],
  },

  'de-ship/de-access': {
    intro: B('An accessible interface is one that people with low vision, motor impairments or screen readers can actually use. Part of it is measurable (contrast, target size), part is structural (labels, focus order), part is language (alternative text). A model helps a lot with structure and language, and is unreliable on measures it reads from pixels. This dojo teaches you to split the work: the AI reviews against named criteria, a checker measures, and you decide. You will leave with a review method you can run on any screen.',
      "Une interface accessible est une interface que les personnes malvoyantes, à mobilité réduite ou utilisant un lecteur d'écran peuvent réellement utiliser. Une partie se mesure (contraste, taille des cibles), une partie tient à la structure (libellés, ordre du focus), une partie au langage (texte alternatif). Un modèle aide beaucoup sur la structure et le langage, et reste peu fiable sur les mesures qu'il lit dans des pixels. Ce dojo vous apprend à répartir le travail : l'IA relit selon des critères nommés, un vérificateur mesure, et vous décidez. Vous repartirez avec une méthode applicable à n'importe quel écran."),
    concepts: [
      { term: B('Contrast ratio', 'Ratio de contraste'),
        def: B('The difference in luminance between text and background, expressed as a ratio. The usual WCAG reference is at least 4.5 to 1 for body text and 3 to 1 for large text and interface components.',
          "La différence de luminance entre le texte et le fond, exprimée sous forme de ratio. La référence WCAG usuelle est d'au moins 4,5 pour 1 pour le texte courant et 3 pour 1 pour les grands textes et les composants d'interface.") },
      { term: B('Focus order', 'Ordre du focus'),
        def: B('The sequence in which keyboard users move through interactive elements. It should follow the visual reading order, and the focused element must always be visible.',
          "La séquence dans laquelle un utilisateur au clavier parcourt les éléments interactifs. Elle doit suivre l'ordre de lecture visuel, et l'élément actif doit toujours être visible.") },
      { term: B('Alternative text', 'Texte alternatif'),
        def: B('The text a screen reader announces instead of an image. It conveys what the image is for; a purely decorative image gets an empty one so it is skipped.',
          "Le texte qu'un lecteur d'écran annonce à la place d'une image. Il transmet sa fonction ; une image purement décorative reçoit un texte vide pour être ignorée.") },
      { term: B('WCAG', 'WCAG'),
        def: B('The Web Content Accessibility Guidelines, the international reference for web accessibility. Many regulations point to them, so naming their criteria makes a review precise.',
          "Les Web Content Accessibility Guidelines, référence internationale de l'accessibilité web. De nombreuses réglementations s'y réfèrent : nommer leurs critères rend une relecture précise.") },
    ],
    walkthrough: {
      title: B('Camille reviews a sign-up form before it goes to development',
        "Camille relit un formulaire d'inscription avant son passage en développement"),
      steps: [
        B('Camille lists the form elements in reading order with their hex codes and text sizes, instead of sending a screenshot. Why: the model then works on your real values, not on compressed pixels.',
          "Camille liste les éléments du formulaire dans l'ordre de lecture avec leurs codes hexadécimaux et tailles de texte, au lieu d'envoyer une capture. Pourquoi : le modèle travaille alors sur vos vraies valeurs, et non sur des pixels compressés."),
        B('She names the criteria to check: contrast, visible labels, focus order and visibility, target size, alternative text. Why: "is it accessible?" gets a verdict; named criteria get a checklist.',
          "Elle nomme les critères à vérifier : contraste, libellés visibles, ordre et visibilité du focus, taille des cibles, texte alternatif. Pourquoi : « est-ce accessible ? » obtient un verdict ; des critères nommés obtiennent une liste de contrôle."),
        B('She forbids final contrast figures and asks for the color pairs to measure. Why: the model may produce a plausible ratio without computing it; the checker is the source of truth.',
          "Elle interdit les chiffres de contraste définitifs et demande les paires de couleurs à mesurer. Pourquoi : le modèle peut produire un ratio plausible sans le calculer ; le vérificateur fait foi."),
        B('The review flags placeholder-only labels and two pairs to measure: light grey placeholder text, and white text on pale green. The checker confirms both are below the threshold. Why: two real failures, found before any code.',
          "La relecture signale les libellés réduits au texte indicatif et deux paires à mesurer : le gris clair du texte indicatif, et le blanc sur vert pâle. Le vérificateur confirme que les deux sont sous le seuil. Pourquoi : deux vrais échecs, trouvés avant tout code."),
        B('Camille adds visible labels, darkens the two colors, marks the leaf illustration as decorative, then completes the form with the keyboard only. Why: the keyboard pass checks what no list can, the real experience.',
          "Camille ajoute des libellés visibles, fonce les deux couleurs, marque l'illustration comme décorative, puis remplit le formulaire au clavier seulement. Pourquoi : le passage au clavier vérifie ce qu'aucune liste ne peut vérifier, l'expérience réelle."),
      ],
    },
    mistakes: [
      { wrong: B('Sending a screenshot and asking "is it accessible?".',
          "Envoyer une capture et demander « est-ce accessible ? »."),
        fix: B('Send elements in reading order with hex codes and sizes, and name the criteria to check.',
          "Envoyez les éléments dans l'ordre de lecture avec codes hexadécimaux et tailles, et nommez les critères à vérifier.") },
      { wrong: B('Writing alternative text that describes the look: "blue bar chart".',
          "Rédiger un texte alternatif qui décrit l'apparence : « graphique à barres bleues »."),
        fix: B('Write what the image is for, here the message of the chart, and leave decorative images with empty alternative text.',
          "Écrivez la fonction de l'image, ici le message du graphique, et laissez les images décoratives avec un texte alternatif vide.") },
      { wrong: B('Marking the screen as compliant on the AI\'s word.',
          "Déclarer l'écran conforme sur la parole de l'IA."),
        fix: B('Measure every contrast pair with a checker and do a keyboard-only pass before signing off.',
          "Mesurez chaque paire de contraste avec un vérificateur et faites un passage au clavier seul avant de valider.") },
    ],
    recap: [
      B('Send real values (hex codes, sizes, order), not a screenshot.', "Envoyez des valeurs réelles (codes, tailles, ordre), pas une capture."),
      B('Name the criteria: contrast, labels, focus, targets, alternative text.', "Nommez les critères : contraste, libellés, focus, cibles, texte alternatif."),
      B('The AI reviews, the checker measures, you decide.', "L'IA relit, le vérificateur mesure, vous décidez."),
      B('A keyboard-only pass tests the experience itself.', "Un passage au clavier seul teste l'expérience elle-même."),
    ],
    further: B('Build a small accessibility checklist for your design system with the criteria you check most often. Add a contrast column next to each color token and fill it with measured ratios. Future reviews start from values already verified.',
      "Construisez une courte liste de contrôle d'accessibilité pour votre design system, avec les critères que vous vérifiez le plus souvent. Ajoutez une colonne de contraste à côté de chaque token de couleur, remplie de ratios mesurés. Les relectures suivantes partent de valeurs déjà vérifiées."),
    more: [
      { q: B('Why is a screenshot a poor basis for checking contrast with an AI?',
          "Pourquoi une capture d'écran est-elle une mauvaise base pour vérifier le contraste avec une IA ?"),
        options: [
          B('Screenshots are always too small for the model', 'Les captures sont toujours trop petites pour le modèle'),
          B('The model sees approximate pixels and may not calculate', 'Le modèle voit des pixels approximatifs et peut ne pas calculer'),
          B('Contrast only matters on printed documents', "Le contraste ne compte que sur les documents imprimés"),
        ],
        answer: 1,
        why: B('Compression and smoothing shift colors, and the model may state a ratio without computing one. Hex codes plus a checker give an exact figure against the threshold.',
          "La compression et le lissage décalent les couleurs, et le modèle peut annoncer un ratio sans le calculer. Codes hexadécimaux et vérificateur donnent un chiffre exact face au seuil.") },
      { q: B('A status is shown only by a red or green dot. Which criterion does it fail?',
          "Un statut n'est indiqué que par une pastille rouge ou verte. Quel critère n'est pas respecté ?"),
        options: [
          B('Information must not rely on color alone', "L'information ne doit pas reposer sur la seule couleur"),
          B('The target size of interactive elements', 'La taille des cibles interactives'),
          B('The focus order of the page', "L'ordre du focus de la page"),
        ],
        answer: 0,
        why: B('People with color vision deficiencies may not tell red from green. Adding a word or an icon ("Paid", "Late") makes the status readable by everyone.',
          "Les personnes daltoniennes peuvent confondre le rouge et le vert. Ajouter un mot ou une icône (« Payé », « En retard ») rend le statut lisible par tous.") },
    ],
  },

  'de-ship/de-assets': {
    intro: B('At the end of a project, a designer hands over files that others will use for months: developers, marketers, printers. Two things go wrong. The files are badly named and nobody knows which one is final, and the rights of photos, fonts and icons are unknown. This dojo shows how to let the AI do the tedious organizing while keeping licenses out of its hands: it writes "unknown" wherever the proof is missing, and you resolve each case. You will leave with a register that protects you and your client.',
      "En fin de projet, un designer livre des fichiers que d'autres utiliseront pendant des mois : développeurs, marketeurs, imprimeurs. Deux choses tournent mal. Les fichiers sont mal nommés et personne ne sait lequel est le bon, et les droits des photos, polices et icônes sont inconnus. Ce dojo montre comment laisser l'IA faire le rangement fastidieux tout en gardant les licences hors de sa portée : elle écrit « inconnue » partout où la preuve manque, et vous traitez chaque cas. Vous repartirez avec un registre qui vous protège, vous et votre client."),
    concepts: [
      { term: B('Asset register', 'Registre des ressources'),
        def: B('A table listing every delivered asset with its name, formats, uses, source and license. It is the reference the client consults before reusing anything.',
          "Un tableau qui liste chaque ressource livrée avec son nom, ses formats, ses usages, sa source et sa licence. C'est la référence que le client consulte avant toute réutilisation.") },
      { term: B('License', 'Licence'),
        def: B('The permission to use a work under conditions: media, duration, territory, number of users, attribution. It lives in a contract or a purchase record, not in a file.',
          "L'autorisation d'utiliser une oeuvre sous conditions : supports, durée, territoire, nombre d'utilisateurs, mention. Elle figure dans un contrat ou une preuve d'achat, pas dans un fichier.") },
      { term: B('Attribution', 'Mention obligatoire'),
        def: B('The credit some licenses require, for example the author\'s name next to a free icon or photo. Forgetting it breaks the license even if the asset was free.',
          "Le crédit exigé par certaines licences, par exemple le nom de l'auteur à côté d'une icône ou d'une photo gratuite. L'oublier enfreint la licence, même si la ressource était gratuite.") },
      { term: B('Naming convention', 'Convention de nommage'),
        def: B('A fixed pattern for file names (project_type_description_size) so that anyone finds the right file without asking.',
          "Un schéma fixe pour les noms de fichiers (projet_type_description_taille), pour que chacun trouve le bon fichier sans avoir à demander.") },
    ],
    walkthrough: {
      title: B('Marc hands over a sports campaign with 40 files and a rights list for the legal team',
        "Marc livre une campagne sportive de 40 fichiers avec une liste des droits pour le service juridique"),
      steps: [
        B('Marc pastes the raw list of 40 file names and his naming convention. Why: renaming follows a rule, which is exactly the kind of task a model does reliably and you can check at a glance.',
          "Marc colle la liste brute des 40 noms de fichiers et sa convention de nommage. Pourquoi : le renommage suit une règle, exactement le type de tâche qu'un modèle fait de manière fiable et que vous vérifiez d'un coup d'oeil."),
        B('He adds a separate list of the sources he knows for sure: stock photo purchases, font licenses. Why: separating facts from files lets the model copy facts instead of guessing them.',
          "Il ajoute une liste séparée des sources qu'il connaît avec certitude : achats de photos, licences de polices. Pourquoi : séparer les faits des fichiers permet au modèle de recopier les faits au lieu de les deviner."),
        B('He requires UNKNOWN for any license not in his list, and forbids "free to use". Why: a plausible license invented by the model is worse than a visible gap.',
          "Il exige INCONNUE pour toute licence absente de sa liste, et interdit « libre de droits ». Pourquoi : une licence plausible inventée par le modèle est pire qu'un trou visible."),
        B('Seven rows come back UNKNOWN, including icons from a free set whose license requires attribution. Why it matters: "free" did not mean "without conditions".',
          "Sept lignes reviennent INCONNUE, dont des icônes d'un jeu gratuit dont la licence exige une mention. Pourquoi c'est important : « gratuit » ne voulait pas dire « sans conditions »."),
        B('Marc resolves each unknown: he finds two purchase receipts, adds the icon credits, replaces one photo he cannot trace. Then he sends the register with the files. Why: the client receives assets they can use without risk.',
          "Marc traite chaque inconnue : il retrouve deux reçus d'achat, ajoute les crédits des icônes, remplace une photo impossible à tracer. Puis il envoie le registre avec les fichiers. Pourquoi : le client reçoit des ressources utilisables sans risque."),
      ],
    },
    mistakes: [
      { wrong: B('Asking the AI to "add the licenses" to your file list.',
          "Demander à l'IA d'« ajouter les licences » à votre liste de fichiers."),
        fix: B('Give it only the licenses you can prove, and require UNKNOWN for everything else.',
          "Donnez-lui seulement les licences que vous pouvez prouver, et exigez INCONNUE pour tout le reste.") },
      { wrong: B('Forgetting fonts in the register because they are not images.',
          "Oublier les polices dans le registre parce que ce ne sont pas des images."),
        fix: B('List every font with its license and number of users; font licenses often limit web or app use.',
          "Listez chaque police avec sa licence et son nombre d'utilisateurs ; les licences de polices limitent souvent l'usage web ou applicatif.") },
      { wrong: B('Treating "free download" as "free to use commercially".',
          "Confondre « téléchargement gratuit » et « usage commercial libre »."),
        fix: B('Read the license terms of each free asset and record any attribution or non-commercial clause in the register.',
          "Lisez les conditions de chaque ressource gratuite et notez dans le registre toute obligation de mention ou clause non commerciale.") },
    ],
    recap: [
      B('Let the AI rename and organize: it follows your rule.', "Laissez l'IA renommer et ranger : elle suit votre règle."),
      B('Licenses come only from your proofs, never from the model.', "Les licences viennent seulement de vos preuves, jamais du modèle."),
      B('Every UNKNOWN is resolved by you before handoff.', "Chaque INCONNUE est traitée par vous avant la livraison."),
      B('Fonts, icons and generated images belong in the register too.', "Polices, icônes et images générées ont aussi leur place dans le registre."),
    ],
    further: B('Start the register at the beginning of your next project, not at the end: each time you download or buy an asset, add its row with the proof. The handoff then takes minutes, and the AI only has to rename and format.',
      "Commencez le registre au début de votre prochain projet, et non à la fin : chaque fois que vous téléchargez ou achetez une ressource, ajoutez sa ligne avec la preuve. La livraison prend alors quelques minutes, et l'IA n'a plus qu'à renommer et mettre en forme."),
    more: [
      { q: B('The AI filled a license as "Creative Commons" for a photo you downloaded months ago. What do you do?',
          "L'IA a rempli « Creative Commons » pour une photo téléchargée il y a des mois. Que faites-vous ?"),
        options: [
          B('Keep it, Creative Commons photos are common', 'Le garder, les photos Creative Commons sont courantes'),
          B('Ask the AI which Creative Commons variant it is', "Demander à l'IA de quelle variante il s'agit"),
          B('Find the original page to confirm, or replace the photo', "Retrouver la page d'origine pour confirmer, ou remplacer la photo"),
        ],
        answer: 2,
        why: B('The model guessed. Creative Commons also has variants that forbid commercial use or require attribution. Only the original source can confirm it; otherwise, replace the photo.',
          "Le modèle a deviné. Creative Commons comporte en outre des variantes qui interdisent l'usage commercial ou exigent une mention. Seule la source d'origine peut confirmer ; sinon, remplacez la photo.") },
      { q: B('Which column of the register saves the most time when the client reuses assets a year later?',
          "Quelle colonne du registre fait gagner le plus de temps quand le client réutilise les ressources un an après ?"),
        options: [
          B('License limits: media, duration, territory', 'Les limites de licence : supports, durée, territoire'),
          B('The original file name before renaming', "Le nom de fichier d'origine avant renommage"),
          B('The date you created the register', 'La date de création du registre'),
        ],
        answer: 0,
        why: B('A year later, the question is "may we use this here?". The limits answer it without digging through old emails, and prevent an expired license from being used by mistake.',
          "Un an plus tard, la question est « pouvons-nous l'utiliser ici ? ». Les limites y répondent sans fouiller de vieux mails, et évitent d'utiliser par erreur une licence expirée.") },
    ],
  },

  'de-ship/de-handoff': {
    intro: B('A handoff is the moment a design becomes someone else\'s job. What the developer does not find in your files, they will decide alone, often under deadline pressure. Most gaps are not in the main screen but in the states around it: loading, empty, error, disabled, very long content. This dojo teaches you to use the AI to list the states you did not draw, to write each behavior with design tokens, and to test the spec with a developer. You will leave with handoffs that raise fewer questions and fewer surprises.',
      "La livraison est le moment où un design devient le travail de quelqu'un d'autre. Ce que le développeur ne trouve pas dans vos fichiers, il le décidera seul, souvent sous la pression du délai. La plupart des manques ne sont pas dans l'écran principal mais dans les états qui l'entourent : chargement, vide, erreur, désactivé, contenu très long. Ce dojo vous apprend à utiliser l'IA pour lister les états non dessinés, à écrire chaque comportement avec des tokens de design, et à tester la spécification avec un développeur. Vous repartirez avec des livraisons qui suscitent moins de questions et moins de surprises."),
    concepts: [
      { term: B('Component state', "État d'un composant"),
        def: B('A distinct situation of a component with its own look and behavior: default, hover, focus, active, disabled, loading, success, error, empty, overflow.',
          "Une situation distincte d'un composant, avec son apparence et son comportement : repos, survol, focus, actif, désactivé, chargement, succès, erreur, vide, débordement.") },
      { term: B('Happy path', 'Cas nominal'),
        def: B('The scenario where everything goes as planned. Mockups usually show only this one, which is why the other states are forgotten.',
          "Le scénario où tout se passe comme prévu. Les maquettes ne montrent souvent que celui-ci, d'où l'oubli des autres états.") },
      { term: B('Design token', 'Token de design'),
        def: B('A named design decision (color.text.error, space.200) used instead of a raw value. When the decision changes, every place that uses the token follows.',
          "Une décision de design nommée (color.text.error, space.200) employée à la place d'une valeur brute. Quand la décision change, tous les endroits qui utilisent le token suivent.") },
    ],
    walkthrough: {
      title: B('Nora completes the handoff of a file upload component before the sprint',
        "Nora complète la livraison d'un composant de dépôt de fichiers avant le sprint"),
      steps: [
        B('Nora describes the component and its limits: CVs and contracts, PDF or DOCX, 10 MB per file, up to 5 files. Why: limits are where most missing states hide.',
          "Nora décrit le composant et ses limites : CV et contrats, PDF ou DOCX, 10 Mo par fichier, jusqu'à 5 fichiers. Pourquoi : c'est dans les limites que se cachent la plupart des états manquants."),
        B('She lists the two states she drew and asks for every missing one, grouped by interaction, progress, errors and content extremes. Why: groups make gaps easier to see than a long flat list.',
          "Elle liste les deux états dessinés et demande tous ceux qui manquent, groupés en interaction, progression, erreurs et contenus extrêmes. Pourquoi : des groupes rendent les manques plus visibles qu'une longue liste plate."),
        B('The AI returns eleven states, each with a behavior and an open question, and flags one as critical: a fifth file too large while four valid files are uploading. Why it is critical: a wrong guess could discard the four valid files.',
          "L'IA renvoie onze états, chacun avec un comportement et une question ouverte, et en signale un comme critique : un cinquième fichier trop lourd pendant le dépôt de quatre fichiers valides. Pourquoi c'est critique : une mauvaise supposition pourrait supprimer les quatre fichiers valides."),
        B('Nora decides: valid files are kept, the large one shows an inline error with the size limit. She writes each state with token names only. Why: the decision is a design choice, and tokens keep the spec aligned with the design system.',
          "Nora tranche : les fichiers valides sont conservés, le fichier trop lourd affiche une erreur en ligne avec la limite de taille. Elle écrit chaque état avec des noms de tokens seulement. Pourquoi : la décision est un choix de design, et les tokens gardent la spécification alignée sur le design system."),
        B('She walks a developer through the spec for ten minutes. Two questions remain: the order of files, and what screen readers announce during upload. She answers both in the spec. Why: the developer\'s questions are the final test of completeness.',
          "Elle parcourt la spécification avec un développeur pendant dix minutes. Deux questions restent : l'ordre des fichiers, et ce qu'annonce le lecteur d'écran pendant le dépôt. Elle répond aux deux dans la spécification. Pourquoi : les questions du développeur sont le test final de complétude."),
      ],
    },
    mistakes: [
      { wrong: B('Handing off only the screen with sample data.',
          "Livrer seulement l'écran rempli de données d'exemple."),
        fix: B('Ask the AI for every missing state grouped by family, and design at least empty, error, loading and very long content.',
          "Demandez à l'IA chaque état manquant groupé par famille, et concevez au minimum le vide, l'erreur, le chargement et le contenu très long.") },
      { wrong: B('Writing raw values in the spec: "#D32F2F, 14 px, 8 px margin".',
          "Écrire des valeurs brutes dans la spécification : « #D32F2F, 14 px, marge de 8 px »."),
        fix: B('Use the names of your design tokens, so the component follows future changes of the design system.',
          "Employez les noms de vos tokens de design, pour que le composant suive les évolutions futures du design system.") },
      { wrong: B('Letting the AI decide the behavior of critical states.',
          "Laisser l'IA décider du comportement des états critiques."),
        fix: B('Let it list states and raise questions, then decide each critical behavior yourself against the user\'s task.',
          "Laissez-la lister les états et poser les questions, puis tranchez vous-même chaque comportement critique au regard de la tâche de l'utilisateur.") },
    ],
    recap: [
      B('The happy path is one state among ten: list the others.', "Le cas nominal est un état parmi dix : listez les autres."),
      B('Look for missing states around limits and errors first.', "Cherchez d'abord les états manquants autour des limites et des erreurs."),
      B('Write behaviors with tokens, not raw values.', "Écrivez les comportements avec des tokens, pas des valeurs brutes."),
      B('The AI lists and questions; you decide critical behaviors.', "L'IA liste et questionne ; vous tranchez les comportements critiques."),
      B('A developer\'s questions are the final completeness test.', "Les questions d'un développeur sont le test final de complétude."),
    ],
    further: B('Turn your state list into a reusable template for each component family (fields, lists, uploads, dialogs). At the next handoff, paste the template with the component: the AI checks it against a list you already trust, and you add only what is new.',
      "Transformez votre liste d'états en modèle réutilisable pour chaque famille de composants (champs, listes, dépôts, fenêtres de dialogue). À la prochaine livraison, collez le modèle avec le composant : l'IA vérifie à partir d'une liste que vous maîtrisez déjà, et vous n'ajoutez que ce qui est nouveau."),
    more: [
      { q: B('A developer asks what a table shows when a name is 80 characters long. What does this reveal?',
          "Un développeur demande ce qu'affiche un tableau quand un nom fait 80 caractères. Qu'est-ce que cela révèle ?"),
        options: [
          B('The developer is overthinking an edge case', 'Le développeur complique un cas marginal'),
          B('The overflow state was not specified', "L'état de débordement n'a pas été spécifié"),
          B('The data should be limited to 20 characters', 'Les données devraient être limitées à 20 caractères'),
        ],
        answer: 1,
        why: B('Long content is a state like any other, and real data always contains it. Decide it (truncate with full text on focus, or wrap) and add it to the spec.',
          "Le contenu long est un état comme un autre, et les vraies données en contiennent toujours. Décidez-le (tronquer avec le texte complet au focus, ou passer à la ligne) et ajoutez-le à la spécification.") },
      { q: B('Which question should you settle before the sprint, rather than leave to the developer?',
          "Quelle question devez-vous trancher avant le sprint, plutôt que de la laisser au développeur ?"),
        options: [
          B('The variable names used in the code', 'Les noms de variables employés dans le code'),
          B('The testing framework of the project', 'Le framework de test du projet'),
          B('The order in which CSS files are loaded', "L'ordre de chargement des fichiers CSS"),
          B('What happens to valid files when one upload fails', "Ce que deviennent les fichiers valides quand un dépôt échoue"),
        ],
        answer: 3,
        why: B('The fate of the user\'s files is a design decision with direct consequences for them. The three other questions are technical choices that belong to the developer.',
          "Le sort des fichiers de l'utilisateur est une décision de design aux conséquences directes pour lui. Les trois autres questions sont des choix techniques qui reviennent au développeur.") },
    ],
  },
}

